TIPS = {'idle': [(29, 78), (28, 81), (27, 79), (29, 78)], 'move': [(41, 80), (44, 78), (41, 78), (39, 78)], 'attack': [(29, 80), (28, 79), (39, 80), (41, 79), (35, 77), (29, 79)], 'hurt': [(25, 80), (25, 79), (25, 80)]}
FX = {'RED': 'flame', 'BLUE': 'crystal', 'GREEN': 'drip', 'CHRONO': 'clock', 'YELLOW': 'spark', 'SILVER': 'swirl', 'CHINESE': 'puff', 'SKELETAL': 'soul', 'COSMIC': 'star', 'UNICORN': 'rainbow', 'WRAITH': 'wisp', 'CLOCKWORK': 'steam', 'FOREST': 'leaf', 'COCKATRICE': 'feather', 'WHALE': 'star', 'FEY': 'fairy', 'ALIEN': 'drip', 'EAGLE': 'feather'}
_CACHE = {}


def _pal(variant):
  key = ('pal', variant)
  p = _CACHE.get(key)
  if p is None:
    p = [None] + [tuple(int(PAL[j + q:j + q + 2], 16) for q in (0, 2, 4)) for j in range(0, len(PAL), 6)]
    swap = VARIANTS.get(variant) if variant else None
    if swap:
      p = [None] + [tuple(swap.get(c, c)) for c in p[1:]]
    _CACHE[key] = p
  return p


def _tip_fx(s, kind, x, y, fr):
  if kind == 'flame':
    for k, c in enumerate(((200, 50, 14), (255, 128, 24), (255, 210, 80))):
      h = 7 - k * 2 + (fr % 2)
      pygame.draw.polygon(s, c, [(x - 3 + k, y + 1), (x, y - h - 2), (x + 3 - k, y + 1)])
  elif kind == 'crystal':
    pygame.draw.polygon(s, (200, 245, 255), [(x - 2, y), (x, y - 7), (x + 2, y)])
    pygame.draw.polygon(s, (130, 212, 240), [(x + 1, y), (x + 4, y - 5), (x + 5, y)])
  elif kind == 'drip':
    dy = (fr * 2) % 7
    pygame.draw.ellipse(s, (170, 255, 90), (x - 1, y + dy, 3, 3))
  elif kind == 'clock':
    pygame.draw.circle(s, (250, 230, 150), (x, y), 3, 1)
    pygame.draw.line(s, (120, 230, 255), (x, y), (x + int(2 * math.cos(fr)), y - int(2 * math.sin(fr))))
  elif kind == 'spark':
    pygame.draw.lines(s, (150, 225, 255), False, [(x, y - 6), (x - 2, y - 3), (x + 1, y - 3), (x - 1, y)])
  elif kind == 'swirl':
    for k in range(3):
      a = fr * 0.9 + k * 2.1
      s.set_at((x + int(4 * math.cos(a)), y - 2 + int(2 * math.sin(a))), (235, 240, 255))
  elif kind == 'puff':
    for k in range(3):
      pygame.draw.ellipse(s, (255, 220, 80), (x - 3 + k * 2, y - 2 - (k % 2) * 2, 3, 3))
  elif kind == 'star':
    c = (255, 255, 255) if fr % 2 else (225, 190, 255)
    pygame.draw.line(s, c, (x - 3, y - 2), (x + 3, y - 2))
    pygame.draw.line(s, c, (x, y - 5), (x, y + 1))
  elif kind == 'rainbow':
    for k, c in enumerate(((255, 64, 64), (255, 200, 60), (80, 220, 100), (70, 160, 255), (180, 90, 255))):
      s.set_at((x - 2 + k, y - 2 - (fr + k) % 2), c)
  elif kind == 'wisp':
    pygame.draw.circle(s, (140, 240, 255), (x, y - 3 - fr % 2), 2)
    s.set_at((x + 1, y - 6 - fr % 2), (230, 255, 255))
  elif kind == 'steam':
    for k in range(2):
      pygame.draw.circle(s, (220, 220, 220) if k else (180, 180, 185), (x - 1 + k * 2, y - 2 - ((fr + k * 2) % 4)), 1 + k)
  elif kind == 'feather':
    pygame.draw.line(s, (220, 60, 40), (x - 2, y), (x + 1, y - 5), 2)
    s.set_at((x + 1, y - 6 + fr % 2), (255, 220, 120))
  elif kind == 'leaf':
    pygame.draw.ellipse(s, (120, 190, 50) if fr % 2 else (170, 200, 70), (x - 2, y - 3 + (fr % 3), 5, 3))
  elif kind == 'fairy':
    for k, c in enumerate(((255, 150, 240), (140, 240, 255), (255, 255, 200))):
      s.set_at((x - 2 + k * 2, y - 2 - (fr + k) % 3), c)
  elif kind == 'soul':
    for k, c in enumerate(((0, 140, 30), (10, 255, 50), (200, 255, 200))):
      h = 6 - k * 2 + (fr % 2)
      pygame.draw.polygon(s, c, [(x - 2 + k // 2, y + 1), (x, y - h - 2), (x + 2 - k // 2, y + 1)])


def baby_frame(name, i, scale=1.0, variant=None, flip=False):
  """variant: dragon key (RED, BLUE, ...). flip=True faces right."""
  w, h, n, data = ANIMS[name]
  i %= n
  k = (name, i, scale, variant, flip)
  s = _CACHE.get(k)
  if s is None:
    pal = _pal(variant)
    raw = _CACHE.get((name, 'raw'))
    if raw is None:
      raw = _CACHE[(name, 'raw')] = zlib.decompress(base64.b64decode(data))
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    base = i * w * h
    for p in range(w * h):
      v = raw[base + p]
      if v:
        s.set_at((p % w, p // w), pal[v] + (255,))
    if variant in FX and name in TIPS:
      tx, ty = TIPS[name][i]
      _tip_fx(s, FX[variant], tx, ty, i)
    if flip:
      s = pygame.transform.flip(s, True, False)
    if scale != 1.0:
      s = pygame.transform.scale(s, (max(1, int(w * scale)), max(1, int(h * scale))))
    if len(_CACHE) > 700:
      for q in [q for q in _CACHE if len(q) == 5]:
        del _CACHE[q]
    _CACHE[k] = s
  return s


def baby_count(name):
  return ANIMS[name][2]
